def transform_rule(grid):
    """
    For each value v ≠ background in input at position (r, c):
    - It appears in output at multiple positions along a diagonal
    - For value 5: diagonal with slope +1, starting from (0, c - r) and going down to (r, c)
    - For value 9: diagonal with slope -1, starting from (0, c + r) and going down to (r, c)
    - Other values: stay only at original position
    """
    h, w = len(grid), len(grid[0])
    bg = 2

    # Find background dynamically
    from collections import Counter
    all_vals = Counter()
    for row in grid:
        for v in row:
            all_vals[v] += 1
    bg = max(all_vals, key=all_vals.get)

    output = [[bg] * w for _ in range(h)]

    # Find all non-background values and their special properties
    # From Demo 2: 5 creates slope +1 diagonal, 9 creates slope -1 diagonal, others stay
    # Let me derive the values from the data itself

    non_bg_pixels = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != bg]

    # Group by value
    values = {}
    for r, c, val in non_bg_pixels:
        if val not in values:
            values[val] = []
        values[val].append((r, c))

    # For each value, compute what the output should be
    for val, pos_list in values.items():
        if val == 5:
            # Slope +1: for each pixel at (r, c), echo to (0, c - r)
            # The base column is origin_col = c - r
            origin_col = pos_list[0][1] - pos_list[0][0]
            # Place at all rows where: col - row = origin_col
            for r in range(h):
                c_diag = origin_col + r
                if 0 <= c_diag < w:
                    output[r][c_diag] = val
        elif val == 9:
            # Slope -1: for each pixel at (r, c), echo to (0, c + r)
            origin_col = pos_list[0][1] + pos_list[0][0]
            # Place at all rows where: col + row = origin_col
            for r in range(h):
                c_diag = origin_col - r
                if 0 <= c_diag < w:
                    output[r][c_diag] = val
        else:
            # Other values stay only at original positions
            for r, c in pos_list:
                output[r][c] = val

    return output

