def transform_2d_logic(grid):
    """
    Rule refined from Demo 2:
    - Identify all non-background pixels
    - Group by value
    - For each value:
      - If all its positions share c-r = constant (slope +1), echo with slope +1
      - If all its positions share c+r = constant (slope -1), echo with slope -1  
      - Other values (scattered) stay at original position only

    The 'echo' fills all cells along the diagonal from row 0 to the value's lowest row.
    """
    h, w = len(grid), len(grid[0])

    from collections import Counter
    bg_counts = Counter()
    for row in grid:
        for v in row:
            bg_counts[v] += 1
    bg = max(bg_counts, key=bg_counts.get)

    # Find all non-background groups
    non_bg = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                non_bg.append((r, c, grid[r][c]))

    # Group by value
    values = {}
    for r, c, val in non_bg:
        if val not in values:
            values[val] = []
        values[val].append((r, c))

    output = [[bg] * w for _ in range(h)]

    for val, pos_list in values.items():
        if len(pos_list) == 1:
            # Single pixel: stays only at original position if background is defined
            # Otherwise check if it's part of a pattern
            output[pos_list[0][0]][pos_list[0][1]] = val
            continue

        # Check for slope patterns
        diffs_c_r = [p[1] - p[0] for p in pos_list]
        sums_c_plus_r = [p[1] + p[0] for p in pos_list]

        is_slope_plus = all(d == diffs_c_r[0] for d in diffs_c_r)
        is_slope_minus = all(s == sums_c_plus_r[0] for s in sums_c_plus_r)

        if is_slope_plus:
            # c - r = origin, echo is c = origin + r
            origin = diffs_c_r[0]
            for r in range(h):
                c_diag = origin + r
                if 0 <= c_diag < w:
                    output[r][c_diag] = val
        elif is_slope_minus:
            # c + r = origin, echo is c = origin - r
            origin = sums_c_plus_r[0]
            for r in range(h):
                c_diag = origin - r
                if 0 <= c_diag < w:
                    output[r][c_diag] = val
        else:
            # Slanted or scattered: stay at original positions
            for r, c in pos_list:
                output[r][c] = val

    return output

